  Object.assign(state,{avScenario:'multi',avView:'trend',avEnabled:true,avDefaultExpense:'wechat',avDefaultIncome:'bank',avDefaultKind:'expense',avHiddenIds:[],avHiddenExpanded:false,avCollapsed:[],avScroll:0,avConversionScope:''});
  const avType=a=>a.type||({bank:'bank_card',wechat:'wechat',alipay:'alipay',credit:'credit_card'}[a.id]||'cash');
  const avTypeLabel=type=>aEditorTypes.find(t=>t[0]===type)?.[1]||'其他';
  function avRows(){if(state.avScenario==='empty')return [];const rows=accounts.filter(a=>state.avScenario!=='single'||a.currency==='CNY');if(state.avScenario==='valuation')rows.push({id:'valuation-demo',type:'investment',name:'长期投资',note:'估值账户',currency:'CNY',amount:50000,icon:'chart-no-axes-combined'});return rows;}
  function avRate(code){return state.avScenario==='missing'&&code==='USD'?null:vQuote(code);}
  const avCardValue=(value,code)=>state.hide?'••••':`${value<0?'-':''}${vSymbol(code)}${money(Math.abs(value))}`;
  const avValue=(value,code)=>state.hide?'••••':`${vSymbol(code)}${money(value)}`;
  function avTotals(){const rows=avRows(),codes=[...new Set(rows.map(a=>a.currency))],multi=codes.length>1;let assets=0,liabilities=0;for(const a of rows){const rate=multi?avRate(a.currency):1;if(rate===null)continue;if(a.amount<0)liabilities+=a.amount*rate;else assets+=a.amount*rate;}return {assets,liabilities,net:assets+liabilities,multi,code:multi?state.fBaseCurrency:codes[0]||state.fBaseCurrency};}
  function avSummary(){const t=avTotals();return `<section class="bc-surface g-asset-summary"><div class="bc-between"><span class="bc-small">${t.multi?'净资产（折 '+t.code+'）':'净资产 · '+t.code}</span><span>${btn('av-privacy',icon(state.hide?'eye-off':'eye'),state.hide?'显示金额':'隐藏金额','bc-icon')}${t.multi?btn('av-conversion',icon('chevron-right'),'查看折算明细','bc-icon'):''}</span></div><div class="g-asset-amount bc-num">${!state.hide&&t.multi?'<span class="av-approx">≈</span> ':''}${t.multi?avValue(t.net,t.code):state.hide?'••••':Number(t.net).toLocaleString('en-US',{maximumFractionDigits:2})}</div><div class="g-asset-metrics"><div><small>总资产</small><strong>${t.multi&&!state.hide?'≈ ':''}${t.multi?avValue(t.assets,t.code):state.hide?'••••':Number(t.assets).toLocaleString('en-US',{maximumFractionDigits:2})}</strong></div><div><small>总负债</small><strong>${t.multi&&!state.hide?'≈ ':''}${t.multi?avValue(Math.abs(t.liabilities),t.code):state.hide?'••••':Number(Math.abs(t.liabilities)).toLocaleString('en-US',{maximumFractionDigits:2})}</strong></div></div></section>`;}
  function avChart(){return `<section class="bc-surface g-asset-chart"><div class="bc-between"><h3>${state.avView==='trend'?'净值趋势':'资产构成'}</h3>${state.avView==='trend'?btn('f-go:networth','详情','查看净值详情','bc-link'):''}</div><div class="g-asset-tabs">${[['trend','净值趋势'],['composition','资产构成']].map(([key,label])=>btn('av-view:'+key,label,label,'',`aria-pressed="${key===state.avView}"`)).join('')}</div>${state.avView==='trend'?`<div class="av-trend" role="img" aria-label="最近十二个月净资产趋势"><svg viewBox="0 0 330 150"><path d="M0 20H330M0 65H330M0 110H330" fill="none" stroke="var(--bc-line)"/><path d="M6 124L35 116L64 119L93 105L122 106L151 86L180 91L209 69L238 61L267 44L296 34L324 15" fill="none" stroke="var(--bc-accent)" stroke-width="2.5"/></svg><div class="bc-chart-axis"><span>25/11</span><span>26/10</span></div></div>${avTotals().multi?'<p class="av-trend-note">按当前汇率折算为主币种；缺少汇率的账户暂不计入。</p>':''}`:`<div class="av-composition"><div class="g-asset-donut"><span>${avValue(avTotals().assets,avTotals().code)}</span></div><p class="bc-small">银行卡 · 现金 · 微信 · 支付宝</p></div>`}</section>`;}
  function avCard(a){const type=avType(a),credit=type==='credit_card',valuation=aEditorTypes.find(t=>t[0]===type)?.[2]==='valuation',hidden=state.avHiddenIds.includes(a.id);return `<article class="bc-surface av-account-card" data-av-card="${a.id}"><div class="bc-between"><button data-action="av-account:${a.id}" class="av-account-name"><span class="av-account-icon"><img src="${aEditorIcons[type]}" alt=""></span><span><b>${esc(a.name)}</b><small>${avTypeLabel(type)} · ${a.currency}</small></span></button>${btn('av-menu:'+a.id,icon('ellipsis'),'账户操作','bc-icon')}</div>${btn('av-account:'+a.id,avCardValue(a.amount,a.currency),'查看'+a.name+'流水','av-account-balance bc-num')}${credit?`<div class="av-credit-progress"><span style="width:${Math.min(100,Math.abs(a.amount)/20000*100)}%"></span></div>`:''}<div class="av-account-foot">${valuation?`<span>当前估值<b>${avCardValue(a.amount,a.currency)}</b></span><span>更新日期<b>10-24</b></span>`:credit?`<span>信用额度<b>${avValue(20000,a.currency)}</b></span><span>当前欠款<b>${avValue(Math.abs(a.amount),a.currency)}</b></span><span>可用额度<b>${avValue(20000+a.amount,a.currency)}</b></span>`:`<span>收入<b>${avValue(a.id==='bank'?12000:0,a.currency)}</b></span><span>支出<b>${avValue(a.id==='bank'?3359.5:0,a.currency)}</b></span>`}</div>${hidden?`<div class="bc-between av-hidden-caption"><small>已隐藏 · 保留历史流水</small>${btn('av-restore:'+a.id,'恢复','恢复'+a.name,'bc-link')}</div>`:''}</article>`;}
  function avGroup(title,rows){if(!rows.length)return '';const types=[...new Set(rows.map(avType))].sort((a,b)=>aEditorTypes.findIndex(t=>t[0]===a)-aEditorTypes.findIndex(t=>t[0]===b)),codes=[...new Set(rows.map(a=>a.currency))],total=rows.reduce((v,a)=>v+a.amount*(avRate(a.currency)??0),0),scope=title==='资产账户'?'assets':'liabilities';return `<section class="av-classification"><div class="av-classification-title"><h3>${title}</h3>${codes.length>1?btn('av-group-detail:'+scope,`${state.hide?'':'≈ '}${avValue(total,state.fBaseCurrency)}${rows.some(a=>avRate(a.currency)===null)?icon('triangle-alert'):''}`,title+'折算明细','bc-link'):`<span class="bc-small">${avValue(rows.reduce((v,a)=>v+a.amount,0),codes[0])}</span>`}</div>${types.map(type=>`<div class="av-type-section">${btn('av-collapse:'+type,`<span class="av-account-icon small"><img src="${aEditorIcons[type]}" alt=""></span><span>${avTypeLabel(type)}</span><small>${rows.filter(a=>avType(a)===type).length}</small>${icon(state.avCollapsed.includes(type)?'chevron-down':'chevron-up')}`,avTypeLabel(type),'av-type-header',`aria-expanded="${!state.avCollapsed.includes(type)}"`)}${state.avCollapsed.includes(type)?'':rows.filter(a=>avType(a)===type).map(avCard).join('')}</div>`).join('')}</section>`;}
  function avAssets(){const rows=avRows(),active=rows.filter(a=>!state.avHiddenIds.includes(a.id)),hidden=rows.filter(a=>state.avHiddenIds.includes(a.id));return `<div class="av-shell">${tophead('资产',`<div class="bc-row">${btn('av-add',icon('plus'),'新增账户','bc-icon')}${btn('av-promo',icon('sparkles'),'蜜蜂家当','bc-icon')}${btn('av-settings',icon('settings-2'),'账户设置','bc-icon')}</div>`)}<div class="av-scroll">${rows.length?avSummary()+avChart()+avGroup('资产账户',active.filter(a=>avType(a)!=='credit_card'))+avGroup('负债账户',active.filter(a=>avType(a)==='credit_card'))+ (hidden.length?`${btn('av-hidden',`${icon('eye-off')}<span>已隐藏 (${hidden.length}) · 合计 ${avValue(hidden.reduce((v,a)=>v+(avRate(a.currency)??0)*a.amount,0),state.fBaseCurrency)}</span>${icon(state.avHiddenExpanded?'chevron-up':'chevron-down')}`,'展开已隐藏账户','av-type-header',`aria-expanded="${state.avHiddenExpanded}"`)}${state.avHiddenExpanded?hidden.map(avCard).join(''):''}`:''):`<div class="av-empty"><p>还没有账户</p>${btn('av-add','新增账户','新增账户','bc-primary')}</div>`}</div></div>`;}
  assets=avAssets;
  function avSettings(){const rows=avRows().filter(a=>!state.avHiddenIds.includes(a.id)),name=id=>rows.find(a=>a.id===id)?.name||'不设置';return `<label class="v4-control-row"><span style="flex:1">启用账户功能</span><input type="checkbox" class="v4-switch" role="switch" data-av-enabled ${state.avEnabled?'checked':''} aria-label="启用账户功能"></label>${avTotals().multi?menuCard([['av-rates','refresh-cw','汇率管理']]):''}${state.avEnabled&&rows.length?menuCard([['av-default:expense','wallet','默认支出账户',name(state.avDefaultExpense)],['av-default:income','wallet','默认收入账户',name(state.avDefaultIncome)]]):''}`;}
  function avConversion(){const rows=avRows().filter(a=>!state.avConversionScope||!state.avHiddenIds.includes(a.id)&&(state.avConversionScope==='assets'&&avType(a)!=='credit_card'||state.avConversionScope==='liabilities'&&avType(a)==='credit_card')),codes=[...new Set(rows.map(a=>a.currency))];return codes.map(code=>{const amount=rows.filter(a=>a.currency===code).reduce((v,a)=>v+a.amount,0),rate=avRate(code);return `<div class="g-asset-conversion-row"><div><b>${code}</b><small>${esc(wCurrencies.find(c=>c.code===code)?wCurrencyName(wCurrencies.find(c=>c.code===code)):code)}</small></div><div><strong>${avValue(amount,code)}</strong>${code===state.fBaseCurrency?'':rate===null?'<small class="g-asset-missing">未折算</small>':`<small>${state.hide?'••••':'≈ '+avValue(amount*rate,state.fBaseCurrency)}</small>`}</div></div>`;}).join('')+(!state.avConversionScope?btn('av-rates','管理汇率 · 缺失币种不计入折算总额','管理汇率','bc-link'):'');}
  function avDefaults(){const selected=state.avDefaultKind==='income'?state.avDefaultIncome:state.avDefaultExpense;return `<label class="ae-search">${icon('search')}<input data-av-search placeholder="搜索" aria-label="搜索默认账户"></label><div class="av-default-list">${menuRow('av-pick:','ban','不设置','',selected?'':icon('check'))}${avRows().filter(a=>!state.avHiddenIds.includes(a.id)).map(a=>`<div data-av-search-value="${esc(a.name+' '+a.currency)}">${menuRow('av-pick:'+a.id,a.icon,a.name,a.currency,a.id===selected?icon('check'):'')}</div>`).join('')}</div>`;}
  const avPreviousModal=rModalBody;
  rModalBody=function(key){if(key==='account-settings')return avSettings();if(key==='asset-default')return avDefaults();if(key==='asset-conversion')return avConversion();if(key==='asset-promo')return `<p class="bc-small">蜜蜂家当 · 管理更多资产</p>${rModalActions('r-close','取消','r-close','知道了')}`;return avPreviousModal(key);};
  Object.assign(rSpecs,{'account-settings':{title:'设置',host:'assets',kind:'sheet'},'asset-default':{title:'默认支出账户',host:'assets',kind:'dialog'},'asset-conversion':{title:'折算明细',host:'assets',kind:'sheet'},'asset-promo':{title:'蜜蜂家当',host:'assets',kind:'dialog'}});
  for(const [key,title] of [['assets-single','资产 · 单币种'],['assets-missing','资产 · 缺失汇率'],['assets-empty','资产 · 空账户'],['assets-hidden','资产 · 隐藏账户'],['assets-valuation','资产 · 估值账户'],['asset-default','默认账户选择'],['asset-conversion','资产折算明细']]){fDefine(key,title,'账户与资产','account/accounts_page.dart',()=>['account-settings','asset-default','asset-conversion'].includes(key)?rModalBody(key):avAssets());aEditorPreviewGroup.appendChild(new Option(title,'flow-'+key));}
  const avPreviousPrepare=rPrepareRoute;
  rPrepareRoute=function(){const scenario={'flow-assets-single':'single','flow-assets-missing':'missing','flow-assets-empty':'empty','flow-assets-hidden':'multi','flow-assets-valuation':'valuation'}[state.page];if(scenario){state.avScenario=scenario;if(state.page==='flow-assets-hidden')state.avHiddenIds=['alipay'];state.page='assets';}avPreviousPrepare();};
  const avPreviousRender=render;
  render=function(){const scroll=phone.querySelector('.av-scroll');if(scroll)state.avScroll=scroll.scrollTop;avPreviousRender();const next=phone.querySelector('.av-scroll');if(next)next.scrollTop=state.avScroll;};
  function avEdit(id){const account=avRows().find(a=>a.id===id),valuation=account&&aEditorTypes.find(t=>t[0]===avType(account))?.[2]==='valuation';rDismiss();navigate(id==='new'?'flow-account-new':valuation?'flow-account-valuation':account&&avType(account)==='credit_card'?'flow-account-credit':'flow-account-edit');aEditorInit();if(account){Object.assign(aEditorDraft,{name:account.name,currency:account.currency,type:avType(account),balance:String(Math.abs(account.amount)),original:account.amount,hidden:state.avHiddenIds.includes(id),hasTransactions:!valuation,group:valuation?'valuation':'daily',lockedGroup:valuation?'valuation':'daily'});render();}}
  function avMenu(id,button){phone.querySelector('.av-popup')?.remove();const bounds=button.getBoundingClientRect(),parent=phone.getBoundingClientRect(),menu=document.createElement('div');menu.className='av-popup';menu.setAttribute('role','menu');menu.innerHTML=btn('av-edit:'+id,`${icon('pencil-line')}编辑账户`,'编辑账户')+(state.avHiddenIds.includes(id)?btn('av-restore:'+id,`${icon('eye')}恢复账户`,'恢复账户'):'');menu.style.top=Math.min(bounds.bottom-parent.top,Number(qPreview.height)-120)+'px';menu.style.right='20px';phone.appendChild(menu);lucide.createIcons({attrs:{width:18,height:18}});}
  root.addEventListener('click',event=>{const el=event.target.closest('[data-action^="av-"]');if(!el){if(!event.target.closest('.av-popup'))phone.querySelector('.av-popup')?.remove();return;}event.preventDefault();event.stopImmediatePropagation();const [action,arg]=el.dataset.action.split(':');phone.querySelector('.av-popup')?.remove();if(action==='av-privacy'){state.hide=!state.hide;render();}else if(action==='av-view'){state.avView=arg;render();}else if(action==='av-settings')rOpenModal('account-settings');else if(action==='av-default'){state.avDefaultKind=arg;rSpecs['asset-default'].title=arg==='income'?'默认收入账户':'默认支出账户';rOpenModal('asset-default');}else if(action==='av-pick'){state[state.avDefaultKind==='income'?'avDefaultIncome':'avDefaultExpense']=arg;rClose();}else if(action==='av-rates'){rDismiss();navigate('flow-rates');}else if(action==='av-conversion'){state.avConversionScope='';rSpecs['asset-conversion'].title='折算明细';rOpenModal('asset-conversion');}else if(action==='av-group-detail'){state.avConversionScope=arg;rSpecs['asset-conversion'].title=arg==='assets'?'资产账户':'负债账户';rOpenModal('asset-conversion');}else if(action==='av-promo')rOpenModal('asset-promo');else if(action==='av-add'||action==='av-edit')avEdit(action==='av-add'?'new':arg);else if(action==='av-account'){state.dAccount=arg;navigate('accountDetail');}else if(action==='av-menu')avMenu(arg,el);else if(action==='av-collapse'){state.avCollapsed=state.avCollapsed.includes(arg)?state.avCollapsed.filter(v=>v!==arg):[...state.avCollapsed,arg];render();}else if(action==='av-hidden'){state.avHiddenExpanded=!state.avHiddenExpanded;render();}else if(action==='av-restore'){state.avHiddenIds=state.avHiddenIds.filter(v=>v!==arg);render();notice('已恢复账户');}},true);
  root.addEventListener('change',event=>{if(event.target.matches('[data-av-enabled]')){state.avEnabled=event.target.checked;rBuildModal();}});
  root.addEventListener('input',event=>{if(event.target.matches('[data-av-search]'))for(const row of phone.querySelectorAll('[data-av-search-value]'))row.hidden=!row.dataset.avSearchValue.toLowerCase().includes(event.target.value.toLowerCase());});
  root.addEventListener('contextmenu',event=>{const row=event.target.closest('[data-av-card]');if(row){event.preventDefault();avEdit(row.dataset.avCard);}});

  const avPreviousAccountDetail=dAccountDetail;
  dAccountDetail=function(){const a=accounts.find(a=>a.id===state.dAccount)||avRows().find(a=>a.id===state.dAccount);if(!a)return avPreviousAccountDetail();const temporary=!accounts.includes(a);if(temporary)accounts.push(a);let html;try{html=avPreviousAccountDetail();}finally{if(temporary)accounts.pop();}const t=document.createElement('template');t.innerHTML=html;const note=t.content.querySelector('.d-identity small');if(note)note.textContent=a.note+' · '+a.currency;const prefix=t.content.querySelector('.d-amount>span');if(prefix)prefix.textContent=vSymbol(a.currency);return t.innerHTML;};

  fDefs['account-settings'].body=avSettings;
